package com.aoo.bcg.gamespi;
import static org.junit.jupiter.api.Assertions.*;import java.util.*;import org.junit.jupiter.api.Test;
class AcyclicDependencyGraphTest{@Test void ordersDependenciesAndRejectsCyclesAndMissingNodes(){var graph=new AcyclicDependencyGraph<>(List.of(new AcyclicDependencyGraph.Node<>("base",Set.of()),new AcyclicDependencyGraph.Node<>("region",Set.of("base")),new AcyclicDependencyGraph.Node<>("play",Set.of("region"))));assertEquals(List.of("base","region","play"),graph.topologicalOrder());assertThrows(IllegalStateException.class,()->new AcyclicDependencyGraph<>(List.of(new AcyclicDependencyGraph.Node<>("a",Set.of("b")),new AcyclicDependencyGraph.Node<>("b",Set.of("a")))));assertThrows(IllegalArgumentException.class,()->new AcyclicDependencyGraph<>(List.of(new AcyclicDependencyGraph.Node<>("a",Set.of("missing")))));}}
